ALTER TABLE store ADD open_minute INT NOT NULL DEFAULT 0;
ALTER TABLE store ADD close_minute INT NOT NULL DEFAULT 1440;
ALTER TABLE store ADD cleaning_minutes INT NOT NULL DEFAULT 15;
ALTER TABLE store ADD early_minutes INT NOT NULL DEFAULT 0;
ALTER TABLE store ADD cancel_minutes INT NOT NULL DEFAULT 60;
ALTER TABLE store ADD enabled BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE room ADD enabled BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE booking ADD hourly_cents INT NOT NULL DEFAULT 0;
ALTER TABLE booking ADD cleaning_minutes INT NOT NULL DEFAULT 15;
ALTER TABLE booking ADD early_minutes INT NOT NULL DEFAULT 0;
ALTER TABLE booking ADD cancel_minutes INT NOT NULL DEFAULT 60;
ALTER TABLE booking ADD remark VARCHAR(255) NOT NULL DEFAULT '';
UPDATE booking SET hourly_cents=(SELECT price_cents FROM room WHERE room.id=booking.room_id);
CREATE TABLE price_package (id VARCHAR(36) PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES room(id), name VARCHAR(80) NOT NULL, minutes INT NOT NULL, amount_cents BIGINT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE staff_account (id VARCHAR(80) PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(500) NOT NULL, role VARCHAR(20) NOT NULL, store_id BIGINT, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE extension_order (id VARCHAR(36) PRIMARY KEY, booking_id VARCHAR(36) NOT NULL REFERENCES booking(id), old_end BIGINT NOT NULL, new_end BIGINT NOT NULL, amount_cents BIGINT NOT NULL, state VARCHAR(30) NOT NULL, request_key VARCHAR(80) NOT NULL UNIQUE, created_at BIGINT NOT NULL);
CREATE TABLE payment_record (id VARCHAR(36) PRIMARY KEY, booking_id VARCHAR(36) NOT NULL REFERENCES booking(id), extension_id VARCHAR(36), amount_cents BIGINT NOT NULL, state VARCHAR(30) NOT NULL, kind VARCHAR(20) NOT NULL, created_at BIGINT NOT NULL, UNIQUE(booking_id,kind,extension_id));
CREATE TABLE refund_record (id VARCHAR(36) PRIMARY KEY, booking_id VARCHAR(36) NOT NULL UNIQUE REFERENCES booking(id), amount_cents BIGINT NOT NULL, state VARCHAR(30) NOT NULL, attempts INT NOT NULL DEFAULT 0, error VARCHAR(255), created_at BIGINT NOT NULL);
CREATE TABLE device_command (id VARCHAR(36) PRIMARY KEY, booking_id VARCHAR(36) NOT NULL REFERENCES booking(id), room_id BIGINT NOT NULL, action VARCHAR(20) NOT NULL, state VARCHAR(30) NOT NULL, attempts INT NOT NULL DEFAULT 0, error VARCHAR(255), created_at BIGINT NOT NULL, UNIQUE(booking_id,action));
CREATE TABLE notification (id VARCHAR(36) PRIMARY KEY, booking_id VARCHAR(36) NOT NULL REFERENCES booking(id), kind VARCHAR(40) NOT NULL, message VARCHAR(255) NOT NULL, created_at BIGINT NOT NULL, UNIQUE(booking_id,kind));
CREATE TABLE id_allocator (kind VARCHAR(20) PRIMARY KEY, next_id BIGINT NOT NULL);
